import subprocess, re, os, difflib
files=[l.strip() for l in open('/tmp/ssk_files.txt') if l.strip()]
def norm(s):
    s=re.sub(r'[`*>#|_-]',' ',s)
    s=re.sub(r'\s+',' ',s)
    return s.lower().strip()
for f in files:
    head=subprocess.run(['git','show',f'HEAD:{f}'],capture_output=True,text=True).stdout.splitlines()
    cur=open(f).read().splitlines()
    sm=difflib.SequenceMatcher(None,[norm(x) for x in head],[norm(x) for x in cur],autojunk=False)
    removed=[]
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag in ('delete','replace'):
            for i in range(i1,i2):
                if head[i].strip():
                    removed.append((i+1,head[i]))
    # coverage check: is each removed line's normalized text a substring of current normalized joined text (allow line joins)?
    curjoin=' '.join(norm(x) for x in cur)
    lost=[]
    for ln,txt in removed:
        n=norm(txt)
        if not n: continue
        if n in curjoin: continue
        # token coverage in any single current line or 2-line window
        toks=n.split()
        best=0
        for j in range(len(cur)):
            for w in (1,2,3):
                cand=' '.join(norm(x) for x in cur[j:j+w])
                r=difflib.SequenceMatcher(None,n,cand).ratio()
                if r>best: best=r
        lost.append((ln,best,txt))
    if lost:
        print('===',f)
        for ln,best,txt in lost:
            print(f'  L{ln} best={best:.2f} {txt[:160]}')
